text(await tools.exec_command({cmd:"cat > /tmp/update_basis.py <<'PY'
import ast
from pathlib import Path
p=Path('src/postgkyl/gpython/basis.py')
s=p.read_text()
start=s.index('# hybrid/gkhybrid are')
end=s.index('\ndef get_basis(', start)
s=s[:start]+'''# Legacy splits used by low-level callers without phase-space metadata.
# Explicit cdim/vdim always select the actual producer basis and cache identity.
_HYBRID_CDIM_VDIM = {
    "hybrid": {2: (1, 1), 3: (2, 1), 4: (3, 1)},
    "gkhybrid": {2: (1, 1), 3: (1, 2), 4: (2, 2), 5: (3, 2)},
}


def cdim_vdim(basis_type: str, ndim: int, *, cdim: int | None = None,
              vdim: int | None = None) -> tuple[int, int]:
  """Validate a basis's configuration/velocity split before entering C."""
  basis_type = basis_type.lower()
  if basis_type not in _HYBRID_CDIM_VDIM:
